//! 🧳️ Source-bound page reads retain one original lease and resume each indivisible page or row action.
use super::{Page,PersistentList,PERSISTENT_PAGE_FANOUT,fits};
use crate::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneBinding,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneRef,RetainedCloneStep}};
const DEPTH:usize=usize::BITS as usize/4;
struct Frame<T:crate::retirement::RetireOwned+Send+Sync+'static>{page:*const Page<T>,next:usize}
impl<T:crate::retirement::RetireOwned+Send+Sync+'static> Copy for Frame<T>{}
impl<T:crate::retirement::RetireOwned+Send+Sync+'static> Clone for Frame<T>{fn clone(&self)->Self{*self}}
/// 🪪️ Every row projection uses the supplied original source; the fixed page pointers remain alive through its bound lease.
pub struct PersistentListRead<T:crate::retirement::RetireOwned+Send+Sync+'static>{original:Option<RetainedCloneBinding>,stack:[Option<Frame<T>>;DEPTH],depth:usize,index:usize,started:bool,done:bool,closing:bool,cleared:bool}
unsafe impl<T:crate::retirement::RetireOwned+Send+Sync+'static> Send for PersistentListRead<T>{}
unsafe impl<T:crate::retirement::RetireOwned+Send+Sync+'static> Sync for PersistentListRead<T>{}
/// 👁️ A returned row borrows its genuine immutable source and transfers no row payload owner.
pub enum PersistentListReadStep<'a,T:crate::retirement::RetireOwned+Send+Sync+'static>{Progress(RetainedCloneProgress),Row(RetainedCloneProgress,usize,RetainedCloneRef<'a,T>),Complete(RetainedCloneProgress)}
impl<T:crate::retirement::RetireOwned+Send+Sync+'static> PersistentListReadStep<'_,T>{pub fn progress(&self)->RetainedCloneProgress{match self{Self::Progress(p)|Self::Row(p,..)|Self::Complete(p)=>*p}}}
impl<T:crate::retirement::RetireOwned+Send+Sync+'static> PersistentListRead<T>{
 /// 🌱️ The enclosing owner admits these fixed cursor headers in its own constructor quote.
 pub fn new()->Self{Self{original:None,stack:[None;DEPTH],depth:0,index:0,started:false,done:false,closing:false,cleared:false}}
 /// 📏️ Quotes the original binding or the complete native traversal header and row output.
 pub fn demand(&self,original:RetainedCloneRef<'_,PersistentList<T>>)->Result<RetirementDemand,ValueError>{if self.closing{return Err(ValueError::invariant("persistent read is closing"))}if let Some(d)=original.binding_demand(&self.original)?{return Ok(d)}if self.done{return Ok(Default::default())}let copy=if !self.started{std::mem::size_of::<bool>()+if original.get().root.is_some(){std::mem::size_of::<Option<Frame<T>>>()+std::mem::size_of::<usize>()}else{std::mem::size_of::<bool>()}}else if self.depth==0{std::mem::size_of::<bool>()}else{let frame=self.stack[self.depth-1].as_ref().ok_or_else(||ValueError::invariant("persistent read frame absent"))?;match unsafe{&*frame.page}{Page::Leaf{len,..}if frame.next<*len=>2*std::mem::size_of::<usize>()+std::mem::size_of::<Option<(usize,RetainedCloneRef<'_,T>)>>(),Page::Branch{children,..}if frame.next<PERSISTENT_PAGE_FANOUT&&children[frame.next].is_some()=>2*std::mem::size_of::<usize>()+std::mem::size_of::<Option<Frame<T>>>(),_=>std::mem::size_of::<usize>()+std::mem::size_of::<Option<Frame<T>>>()}};Ok(RetirementDemand{copy_bytes:copy,depth:1,..Default::default()})}
 fn projects_row(&self)->bool{if !self.started||self.depth==0{return false}self.stack[self.depth-1].as_ref().is_some_and(|frame|matches!(unsafe{&*frame.page},Page::Leaf{len,..}if frame.next<*len))}
 pub fn advance_work_demand(&self,original:RetainedCloneRef<'_,PersistentList<T>>)->Result<u64,ValueError>{original.binding_demand(&self.original)?;if self.original.is_none(){return original.binding_work_demand(&self.original)}if self.done{return Ok(0)}Ok(RetainedCloneRef::<PersistentList<T>>::check_binding_work(&self.original)+1+if self.projects_row(){5}else{0})}
 /// ▶️ Publishes an original row into its caller-resident borrowed slot after the real native action.
 pub fn advance_into<'a,'r>(&mut self,original:RetainedCloneRef<'a,PersistentList<T>>,output:&mut Option<(usize,RetainedCloneRef<'a,T>)>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{
  if output.is_some(){return Err(ValueError::invariant("persistent read row output occupied"))}let d=self.demand(original)?;let work=self.advance_work_demand(original)?;if self.done{return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))}if !fits(d,effect.grant())||effect.remaining_work_units()?<work{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if self.original.is_none(){let turn=original.bind(&mut self.original,effect);return Ok(reply.complete(turn.result.map(|progress|RetainedCloneStep::Progress(progress.unwrap_or_default()))))}let checked=original.check_binding_paid(&self.original,effect);match checked.result{Ok(Some(true))=>{},Ok(_)=>return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default())))),Err(error)=>return Ok(reply.complete(Err(error)))}let local_work=1+if self.projects_row(){5}else{0};match effect.performed(local_work){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"persistent read exceeded Work")))),Err(error)=>return Ok(reply.complete(Err(error)))}let p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};let result=(||{if !self.started{self.started=true;if let Some(root)=original.get().root.as_ref(){self.stack[0]=Some(Frame{page:root.get(),next:0});self.depth=1}else{self.done=true}return Ok(if self.done{RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}if self.depth==0{self.done=true;return Ok(RetainedCloneStep::Complete(p))}let slot=self.depth-1;let frame=self.stack[slot].as_mut().ok_or_else(||ValueError::invariant("persistent read frame absent"))?;let page=unsafe{&*frame.page};match page{Page::Leaf{rows,len}=>{if frame.next==*len{self.stack[slot]=None;self.depth-=1;return Ok(RetainedCloneStep::Progress(p))}let row=rows[frame.next].as_ref().ok_or_else(||ValueError::invariant("persistent read dense row absent"))?.get()as*const T;let index=self.index;let next=index.checked_add(1).ok_or_else(||ValueError::invariant("persistent read index overflow"))?;let projected=original.project(index,|_|unsafe{&*row});frame.next+=1;self.index=next;*output=Some((index,projected));Ok(RetainedCloneStep::Progress(p))},Page::Branch{children,..}=>{if frame.next==PERSISTENT_PAGE_FANOUT||children[frame.next].is_none(){self.stack[slot]=None;self.depth-=1;return Ok(RetainedCloneStep::Progress(p))}if self.depth==DEPTH{return Err(ValueError::literal(ValueRefusalKind::DepthLimit,"persistent read exceeds page depth"))}let child=children[frame.next].as_ref().ok_or_else(||ValueError::invariant("persistent read dense child absent"))?.get();frame.next+=1;self.stack[self.depth]=Some(Frame{page:child,next:0});self.depth+=1;Ok(RetainedCloneStep::Progress(p))}}})();Ok(reply.complete(result))
 }
 /// 🛑️ Starting closure is a separately funded native header transition.
 pub fn is_closing(&self)->bool{self.closing}
 pub fn begin_close_demand(&self)->RetirementDemand{if self.closing{Default::default()}else{RetirementDemand{copy_bytes:std::mem::size_of::<bool>(),depth:1,..Default::default()}}}
 pub fn begin_close_work_demand(&self)->u64{u64::from(!self.closing)}
 pub fn begin_close_paid(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome{let d=self.begin_close_demand();if self.closing{return crate::RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}let remaining=match effect.remaining_work_units(){Ok(value)=>value,Err(error)=>return crate::RetainedWorkOutcome{result:Err(error),work:0}};if !fits(d,effect.grant())||remaining<1{return crate::RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}let before=effect.performed_work();let result=match effect.performed(1){Ok(true)=>{self.closing=true;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))},Ok(false)=>Err(ValueError::literal(ValueRefusalKind::WorkLimit,"persistent read close start exceeded Work")),Err(error)=>Err(error)};crate::RetainedWorkOutcome{result,work:effect.performed_work()-before}}
 /// ♻️ Quotes the actual fixed frame clear or selected original binding.
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.cleared{return Ok(RetirementDemand{copy_bytes:std::mem::size_of::<[Option<Frame<T>>;DEPTH]>()+std::mem::size_of::<usize>()+std::mem::size_of::<bool>(),depth:1,..Default::default()});}RetainedCloneBinding::close_demand(&self.original,body)}
 pub fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if !self.cleared{Ok(1)}else{RetainedCloneBinding::close_work_demand(&self.original,body)}}
 pub fn requires_original_birth(&self)->bool{self.cleared&&RetainedCloneBinding::requires_original_birth(&self.original)}
 pub fn requires_original_control(&self)->bool{self.cleared&&RetainedCloneBinding::requires_original_control(&self.original)}
 pub fn close_original_birth_step(&mut self,loan:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->semio_framework_value_retirement::OriginalRetirementPoll{if !self.closing||!self.cleared{return semio_framework_value_control_contract::RetainedWorkPoll::Complete(crate::RetainedWorkOutcome{result:Err(ValueError::invariant("persistent read original Birth has no selected binding").into()),work:0})}RetainedCloneBinding::close_original_birth_step(&mut self.original,loan,grant)}
 /// 🪜️ The selected original binding writes directly to the caller-owned reply.
 pub fn close_into<'r>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if !self.closing{return Err(ValueError::invariant("persistent read close not started"))}if self.cleared{return RetainedCloneBinding::close_into(&mut self.original,body,effect,reply)}let d=self.close_demand(body)?;if !fits(d,effect.grant())||effect.remaining_work_units()?<1{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(1){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"persistent read frame clear exceeded Work").into()))),Err(error)=>return Ok(reply.complete(Err(error.into())))}self.stack=[None;DEPTH];self.depth=0;self.cleared=true;Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
 pub fn recover_close_into<'r>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if !self.closing||!self.cleared{return Err(ValueError::invariant("persistent read recovery has no selected binding"))}RetainedCloneBinding::recover_close_into(&mut self.original,body,effect,reply)}
 pub fn close_original_into<'r>(&mut self,loan:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if !self.closing||!self.cleared{return Err(ValueError::invariant("persistent read original close has no selected binding"))}RetainedCloneBinding::close_original_into(&mut self.original,loan,body,effect,reply)}
 pub fn recover_close_original_into<'r>(&mut self,loan:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if !self.closing||!self.cleared{return Err(ValueError::invariant("persistent read original recovery has no selected binding"))}RetainedCloneBinding::recover_close_original_into(&mut self.original,loan,body,effect,reply)}
 /// 🫙️ No original page address or source alias survives terminal closure.
 pub fn terminal_is_empty(&self)->bool{self.cleared&&self.original.is_none()&&self.depth==0}
}
impl<T:crate::retirement::RetireOwned+Send+Sync+'static> Drop for PersistentListRead<T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"immutable read requires original source closure");}}
